    title = "Анализ карточек товара, цен и условий поставки"
    filename = "Лекция_Модуль_05_Лекция_03_Анализ_карточек_товара,_цен_и_условий_поставки.docx"
    doc = Document()
    configure_document(doc, "ООО «Экспальянс» | «Ведение бизнеса с Китаем» — 144 ч. | Модуль 5 | Лекция 3")
