    add_section(doc, 2, "Аннотация", P("""
    Лекция посвящена профессиональному чтению карточек товара на китайских электронных торговых площадках. Карточка рассматривается не как готовая спецификация и не как безусловная оферта, а как маркетингово-информационный объект, содержащий данные разной степени надежности. Слушатель учится отделять идентифицирующие сведения от рекламных формулировок, сопоставлять варианты товара, единицы измерения, упаковку, минимальную партию, ценовые ступени, сроки изготовления, условия поставки и сведения о соответствии.

    Материал исходит из того, что экосистема платформ и приемы поиска поставщиков уже изучены. В центре внимания находится переход от найденной карточки к нормализованной закупочной позиции: что именно предлагается, за какую цену, при каком объеме, в какой комплектации, на каком базисе и какие расходы остаются за пределами отображенной цены. Рассматриваются Alibaba.com, 1688.com и Made-in-China.com, однако методика применима и к другим площадкам.

    Практический результат лекции — умение составить протокол анализа карточки, выявить неопределенности и подготовить перечень вопросов, необходимых до запроса окончательной котировки. Коммуникация с продавцом, механизмы защиты покупателя и переход к внешнеторговому контракту подробно рассматриваются в следующих лекциях модуля.
    """))

    add_section(doc, 3, "Цель лекции", P("""
    Сформировать у слушателей системный навык анализа карточек товара на китайских B2B- и B2C-платформах, позволяющий преобразовать разрозненные сведения о товаре, цене и поставке в сопоставимые коммерческие данные и определить, какие параметры должны быть подтверждены до принятия закупочного решения.
    """))

    add_section(doc, 4, "Задачи лекции", bullets=[
        "раскрыть информационную структуру карточки товара и различия между рекламным описанием, техническими параметрами и условиями конкретной сделки;",
        "научить идентифицировать товар, модель, вариант, единицу цены, количество в упаковке и минимальную партию;",
        "показать порядок проверки ценовых ступеней, валюты, налоговой составляющей и дополнительных расходов;",
        "разобрать значение образцов, кастомизации, оснастки, упаковки, маркировки и сроков изготовления;",
        "объяснить, почему базис Incoterms® требует указания правила, поименованного места и редакции;",
        "связать данные карточки с логистикой, таможенной стоимостью, классификацией товара и оценкой соответствия в ЕАЭС;",
        "сформировать алгоритм нормализации карточек нескольких поставщиков и выявления красных флагов;",
        "подготовить слушателя к последующей коммуникации на площадке и оформлению проверяемых условий заказа.",
    ])

    add_learning_results(doc,
        know=[
            "назначение и ограничения карточки товара как источника коммерческой и технической информации;",
            "состав обязательных для анализа элементов: модель, вариант, единица, MOQ, ценовой диапазон, упаковка, срок, базис, документы;",
            "различия между EXW, FCA, FOB, CFR, CIF и DAP в части распределения расходов и рисков;",
            "факторы, из-за которых отображенная цена отличается от фактической цены заказа и полной импортной себестоимости;",
            "роль технической спецификации, контрольного образца, требований к маркировке и подтверждению соответствия;",
            "типовые признаки неполной, противоречивой или вводящей в заблуждение карточки товара."
        ],
        be_able=[
            "установить, к какому варианту, количеству и комплектности относится цена;",
            "перевести параметры карточки в нормализованную таблицу сравнения;",
            "рассчитать предварительную стоимость единицы с учетом упаковки, доставки, таможенных платежей и обязательных процедур;",
            "выявить отсутствующие параметры и сформулировать вопросы для последующей котировки;",
            "сопоставить фото, чертежи, спецификацию и сведения о сертификатах без подмены проверки рекламными заявлениями;",
            "зафиксировать доказательства анализа карточки с датой, ссылкой, скриншотами и версией данных."
        ],
        possess=[
            "чек-листом чтения карточки товара;",
            "матрицей нормализации цен и условий поставки;",
            "методикой предварительного расчета landed cost;",
            "приемами проверки логической согласованности количества, цены, упаковки, веса и срока;",
            "навыком подготовки протокола неопределенностей и перечня подтверждающих документов."
        ])

    add_heading(doc, "6. План лекции.", 1)
    add_table(doc, ("№", "Учебный вопрос", "Практический результат"), [
        ("1", "Карточка товара как источник данных и ее доказательственные ограничения", "Разделение факта, заявления и допущения"),
        ("2", "Идентификация товара, вариантов, единиц и комплектации", "Корректная закупочная позиция"),
        ("3", "Цена, MOQ, дополнительные расходы и полная стоимость", "Нормализованная ценовая модель"),
        ("4", "Срок, упаковка, поставка, логистика и соответствие", "Перечень подтверждаемых условий"),
        ("5", "Алгоритм, чек-лист, мини-кейсы и практическое задание", "Протокол анализа карточки"),
    ])

    add_heading(doc, "7. Основной текст лекции.", 1)

    add_main_subsection(doc, "1", "Карточка товара: витрина, источник данных и набор гипотез", P("""
    Карточка товара создается для привлечения внимания и генерации запроса, поэтому ее структура подчинена логике электронной торговли. На первом экране обычно размещаются фотография, краткий заголовок, диапазон цены, минимальный объем, признаки поставщика и кнопка связи. Ни один из этих элементов сам по себе не доказывает, что именно такой товар будет изготовлен для конкретного покупателя на отображенных условиях. Цена может относиться к базовой версии, большому объему, внутренней поставке по Китаю или комплектации без необходимых аксессуаров.

    Профессиональный анализ начинается с классификации каждого утверждения. Проверяемый факт имеет однозначный источник и относится к конкретному варианту: например, чертеж с номером версии, масса нетто одной единицы или размер транспортной коробки. Заявление поставщика требует подтверждения: «экспортное качество», «международный сертификат», «срок семь дней». Допущение аналитика должно быть помечено отдельно: расчетный объем коробки, предполагаемый код ТН ВЭД, ориентировочная стоимость доставки. Смешение трех категорий создает ложную определенность.

    Карточку следует воспринимать как вход в процесс уточнения, а не как финальную спецификацию. Ее ценность состоит в выявлении доступных вариантов, диапазонов и вопросов. Надежная закупочная документация появляется только после того, как значения подтверждены в котировке, техническом приложении, образце и договоре либо заказе на платформе.
    """))

    add_main_subsection(doc, "2", "Идентификация товара и границы анализируемой позиции", P("""
    До сравнения цены необходимо установить предмет сравнения. В карточке могут одновременно демонстрироваться несколько моделей, размеров, материалов и цветов, а заголовок содержит широкий набор поисковых слов. Покупатель должен выделить конкретную закупочную позицию: коммерческое наименование, модель, артикул поставщика, собственный артикул покупателя, назначение, ключевые характеристики и версию. Для комплектного изделия фиксируется полный состав, включая кабели, крепеж, зарядные устройства, расходные материалы, инструкции и запасные элементы.

    Особую опасность представляет «семейная» карточка, где фотографии относятся к разным исполнениям, а минимальная цена — к самому простому. На 1688 нередко применяется выбор свойств через иероглифы, и автоматический перевод может скрывать разницу между «одной деталью», «комплектом», «образцом», «внутренней упаковкой» и «ящиком». На Alibaba.com и Made-in-China.com аналогичная проблема возникает при объединении OEM-вариантов и стандартных моделей.

    Правильная фиксация позиции должна позволять независимому сотруднику повторить анализ. Недостаточно записать «насос из карточки». Необходимо указать ссылку, дату доступа, выбранный SKU, изображение выбранного варианта, набор параметров и все исключения. Если модель отсутствует, покупатель присваивает временный идентификатор и требует, чтобы продавец использовал его во всех последующих документах.
    """))

    add_main_subsection(doc, "3", "Заголовок, категория и поисковые ключи", P("""
    Заголовок карточки часто перегружен ключевыми словами и не является техническим описанием. Слова «factory», «manufacturer», «professional», «CE», «custom», «wholesale» повышают видимость в поиске, но не подтверждают статус изготовителя, наличие конкретного документа или готовность выполнить индивидуальный заказ. Категория платформы также служит прежде всего навигации и может не совпадать с таможенной классификацией либо областью применения технического регламента.

    Аналитик использует заголовок для формирования терминологической карты: английские и китайские названия изделия, отраслевые синонимы, обозначения материала, технологии и модели. Затем эти сведения проверяются по подробным параметрам, маркировке на фото, каталогу производителя и техническим документам. Если в заголовке указан один материал, а в таблице параметров другой, расхождение заносится в протокол и не разрешается предположением в пользу более выгодного варианта.

    Нельзя переносить категорию площадки в декларацию на товары или использовать рекламное название как основание для кода ТН ВЭД ЕАЭС. Классификация зависит от объективных характеристик, функции, состава и степени обработки. Карточка может дать исходные сведения, но окончательная классификационная гипотеза формируется по документам и при необходимости уточняется с таможенным специалистом.
    """))

    add_main_subsection(doc, "4", "Фотографии, видео и визуальные доказательства", P("""
    Визуальные материалы помогают понять конструкцию и комплектацию, однако могут быть заимствованы, отретушированы или относиться к более дорогой версии. Следует разделять студийные изображения, фотографии реального изделия, производственные кадры, схемы и сертификаты, загруженные как картинки. Студийное фото показывает внешний вид, но редко подтверждает размеры, материал или серийное производство. Производственное видео ценно только при наличии связи с конкретной компанией, датой и рассматриваемой моделью.

    Полезно проверять логическую согласованность изображения: одинаковы ли разъемы на разных кадрах, совпадает ли маркировка, есть ли масштаб, видна ли упаковка, соответствует ли цвет выбранному варианту. Встроенная линейка или подпись размера не заменяет чертеж с допусками. Фотография знака соответствия не доказывает наличие действующего документа и применимость к конкретному изделию.

    При анализе формируется перечень необходимых подтверждений: фото шильдика крупным планом, видео работы изделия, фотографии внутренней конструкции, упаковки, серийного номера и комплекта. Такие запросы относятся уже к последующей коммуникации, но карточка должна заранее показать, какие доказательства отсутствуют. Скриншоты сохраняются с адресной строкой и датой, чтобы зафиксировать исходное состояние предложения.
    """))

    add_main_subsection(doc, "5", "Технические параметры: полнота, измеримость и непротиворечивость", P("""
    Таблица параметров может содержать материал, размер, мощность, напряжение, производительность, точность, температуру, ресурс и другие показатели. Для каждой характеристики необходимо определить единицу измерения, допустимое отклонение, метод испытания и применимость к выбранной модели. Значение «220 V» без частоты, типа вилки, диапазона напряжения и класса защиты недостаточно для электротехнического изделия. Формулировка «нержавеющая сталь» не отвечает на вопрос о марке, составе и поверхности.

    Измеримые параметры следует преобразовать в проект спецификации. Покупатель отмечает критические характеристики, влияющие на безопасность, совместимость, таможенную классификацию и потребительские свойства. Для них недопустимы ссылки на «обычное качество» или «стандарт фабрики» без приложения самого стандарта. Если платформа показывает значения в нескольких местах, применяется матрица перекрестной проверки: заголовок, свойства, инфографика, PDF-каталог, ответы продавца.

    Противоречие не всегда означает обман: карточка могла устареть, объединять версии или содержать ошибку перевода. Однако оно всегда означает невозможность считать параметр согласованным. До уточнения в расчетах используется консервативный сценарий, а в протоколе указывается влияние неопределенности на цену, логистику и соответствие.
    """))

    add_main_subsection(doc, "6", "Единица цены, упаковочная единица и количество", P("""
    Цена может быть указана за штуку, пару, набор, килограмм, метр, квадратный метр, коробку или минимальную упаковку. Английское «piece» иногда используется продавцом для комплекта, а китайские обозначения могут отражать внутреннюю торговую практику. До расчета необходимо установить базовую физическую единицу и коэффициент пересчета. Например, коробка содержит 24 изделия, но цена показана за внутреннюю пачку из шести; ошибка увеличивает расчет в четыре раза.

    Упаковочная единица влияет не только на цену, но и на MOQ, вес, объем, маркировку и риск повреждения. Следует фиксировать количество изделий во внутренней и транспортной упаковке, массу нетто и брутто, размеры коробки, число коробок на паллете и допустимость смешивания вариантов. Для товаров с сериями или партиями требуется правило прослеживаемости.

    Логическая проверка выполняется через контрольные расчеты. Объем коробки сопоставляется с числом изделий и их габаритами; масса брутто должна быть больше массы нетто; заявленное число коробок в кубическом метре проверяется арифметически. Существенное несоответствие превращается в вопрос поставщику и может изменить выбор способа перевозки.
    """))

    add_main_subsection(doc, "7", "MOQ и минимальная экономически допустимая партия", P("""
    MOQ — минимальное количество, которое поставщик готов принять в одном заказе или варианте. Карточка может показывать общий MOQ, тогда как фактический минимум применяется отдельно к цвету, размеру, логотипу, упаковке или производственной партии. Для стандартного товара возможна смешанная партия со склада, а для OEM-производства возникает отдельный минимум сырья, печати или настройки оборудования.

    Низкий MOQ не всегда означает выгодное условие. Он может относиться к образцу по повышенной цене, к остаткам, к нейтральной упаковке либо к поставке по Китаю без экспортного оформления. Высокий MOQ необходимо оценивать вместе с оборачиваемостью, гарантийным запасом, сроком годности, стоимостью хранения и риском изменения модели. Покупатель определяет не только минимум продавца, но и собственную экономически допустимую партию.

    В протоколе анализа указываются четыре значения: MOQ карточки, MOQ выбранного варианта, MOQ кастомизации и рекомендуемый объем тестового заказа. Если они неизвестны, цена считается ориентировочной. Сравнивать поставщиков по цене при разных MOQ нельзя без приведения к единому объему или сценариям.
    """))

    add_main_subsection(doc, "8", "Ценовые ступени и диапазоны", P("""
    Диапазон цены обычно связан с количеством, но может также зависеть от модели, материала, цвета, комплектации, сезона и способа поставки. Отображение «1,20–4,80 долл.» без таблицы соответствия не позволяет определить цену выбранного изделия. Даже если площадка показывает ступени, продавец может уточнить их после получения спецификации, поскольку карточка создавалась для типовой версии.

    Каждую ценовую ступень необходимо записывать с условием: количество, единица, вариант, валюта, налоговый статус, упаковка, базис, срок действия и включенные услуги. Цена образца выделяется отдельно. Для 1688 важно проверить, включает ли цена китайский НДС, предусмотрен ли счет-фактура фапяо, доступна ли продажа иностранному покупателю и кто будет экспортной стороной. Для международной платформы необходимо уточнить банковские комиссии и платежные сборы.

    Нормализация предполагает расчет цены на одинаковой базе. Если один продавец предлагает 1 000 единиц EXW, а другой 2 000 единиц FOB, сравнение начинается с пересчета к одинаковому количеству и поименованной точке. Разница между ценой карточки и подтвержденной котировкой фиксируется; повторяющиеся существенные изменения являются сигналом качества коммерческой информации.
    """))

    add_main_subsection(doc, "9", "Валюта, налоги и специфика 1688", P("""
    Валюта отображения определяется настройками площадки, регионом и типом аккаунта. Пересчет интерфейса может быть справочным и не означать, что продавец выставит счет в выбранной валюте. На 1688 расчеты обычно ориентированы на внутренний рынок КНР и юани, а экспортная сделка может потребовать посредника, экспортера или отдельную международную структуру группы. Это меняет состав документов, платежный маршрут и цену.

    Налоговая составляющая должна рассматриваться отдельно. Внутренняя цена с китайским налогом, цена без фапяо и экспортная цена — не одно и то же. Покупателю нельзя самостоятельно вычитать процент, не установив правовую и коммерческую модель. Аналогично отметка «tax excluded» не означает отсутствие всех налогов и сборов в импортирующей стране.

    Для расчета используется валюта контракта и курс сценария. Желательно рассматривать базовый, неблагоприятный и стрессовый курс, особенно если между анализом карточки и платежом пройдет время. Валютный риск не должен маскировать различия в комплектации и базисе; сначала нормализуются физические и коммерческие условия, затем проводится пересчет.
    """))

    add_main_subsection(doc, "10", "OEM, ODM и кастомизация", P("""
    Знаки OEM и ODM в карточке могут означать готовность обсуждать индивидуальные изменения, но не доказывают наличие разработчиков, прав на конструкцию или свободной мощности. Кастомизация бывает поверхностной — логотип, цвет, наклейка, коробка — и конструктивной — материал, размеры, электронная схема, программное обеспечение, оснастка. Эти уровни имеют разные сроки, минимальные партии и риски.

    Анализ карточки должен выявить, какие изменения показаны как стандартные опции, а какие требуют новой котировки. Важно установить владельца чертежей, файлов, пресс-форм, прошивки, дизайна упаковки и результатов разработки. Фраза «free logo» может действовать только при определенном количестве и одном цвете печати, а цена не включает клише, форму или подготовку макета.

    Нельзя считать образцы с чужим брендом доказательством законной возможности изготовить аналог. Покупатель проверяет собственные права на обозначения и дизайн, требует исключить несанкционированное использование чужих объектов и не передает производственные файлы до минимальной проверки контрагента. В карточке фиксируются только исходные признаки; юридические условия оформляются отдельно.
    """))

    add_main_subsection(doc, "11", "Образцы и цена подтверждения", P("""
    Карточка может обещать бесплатный образец, но фактически покупатель оплачивает доставку, залог, изготовление индивидуального варианта или повышенную цену. Следует различать складской образец, предсерийный образец по требованиям покупателя, контрольный эталон и случайно отобранную единицу из партии. Они отвечают на разные вопросы и имеют разную доказательственную силу.

    Складской образец позволяет оценить общее качество и коммуникацию, но не подтверждает будущую кастомизацию. Предсерийный образец должен иметь номер версии и перечень согласованных отличий. Контрольный эталон подписывается или иным образом идентифицируется сторонами и используется при приемке, если это предусмотрено договором. Отобранный образец подтверждает состояние конкретной партии только при контролируемой выборке.

    При чтении карточки отмечаются стоимость образца, срок подготовки, возможность возврата суммы при заказе, способ доставки и документы. Если обещание «sample available» не раскрыто, оно считается приглашением к запросу, а не ценовым условием. Расходы на подтверждение включаются в стоимость проекта, особенно при сложном или регулируемом товаре.
    """))

    add_main_subsection(doc, "12", "Оснастка, формы и единовременные расходы", P("""
    Для литья, штамповки, печати, упаковки и специальных испытаний могут потребоваться формы, матрицы, клише, программирование, настройка линии и лабораторные работы. Эти расходы часто отсутствуют в первой цене. Карточка с низкой ценой единицы может предполагать, что покупатель отдельно оплатит дорогостоящую оснастку и большой стартовый объем.

    Аналитик формирует перечень NRE — невозвратных единовременных затрат: разработка, образец, форма, тестовый стенд, сертификационные образцы, перевод инструкции, дизайн упаковки. Для каждой позиции устанавливаются стоимость, срок, владелец, место хранения, ресурс, порядок ремонта и возможность передачи. Амортизация по планируемому объему позволяет сравнить предложения корректно.

    В карточке редко раскрывается правовой режим оснастки, поэтому отсутствие информации не трактуется в пользу покупателя. До вложения средств требуется отдельное письменное условие. На этапе анализа достаточно отметить, что цена товара не включает подтвержденные права на форму и что экономическая модель должна учитывать риск повторного заказа или смены поставщика.
    """))

    add_main_subsection(doc, "13", "Срок изготовления, готовность к отгрузке и календарный риск", P("""
    Показатель lead time может обозначать срок производства после оплаты, срок обработки складского заказа, время до передачи перевозчику или приблизительный период. Он не всегда включает утверждение макета, изготовление образца, закупку сырья, инспекцию, экспортное оформление и бронирование перевозки. Формулировка «7 days» без начальной точки и условий не является полноценным обязательством.

    Срок анализируется как цепочка этапов: подтверждение заказа, техническое согласование, аванс, подготовка материалов, производство, контроль, упаковка, готовность груза, передача перевозчику. Для каждого этапа требуется дата или продолжительность, зависимость и доказательство завершения. Китайские праздничные периоды, сезонная загрузка и ограничения сырья учитываются не как стереотип, а как конкретные календарные факторы, подтверждаемые поставщиком и логистом.

    При сравнении карточек выбирается единая точка: например, дата готовности груза FCA склад поставщика или FOB конкретный порт. Обещание более короткого срока оценивается вместе с мощностью и наличием товара. Нереалистично короткий срок может означать складскую другую модель, субподряд или неполное понимание требований.
    """))

    add_main_subsection(doc, "14", "Наличие на складе и производственная доступность", P("""
    Метка «in stock» может отражать техническую настройку карточки, остаток стандартной версии или наличие только части компонентов. Для кастомизированного товара складское наличие обычно не решает вопрос срока. На B2B-площадках карточка нередко поддерживается годами и не синхронизирована с реальным складом.

    Анализатор проверяет, указано ли доступное количество, дата обновления, местонахождение склада и возможность резервирования. Если товар заявлен на зарубежном складе, уточняются собственник, страна происхождения, документы импорта и применимость цены. Остатки могут иметь старую версию, ограниченный срок годности или отличаться по маркировке.

    Производственная доступность не доказывается счетчиком сделок. На этапе карточки можно лишь сформулировать гипотезу и запросить календарь, фотографии партии, номера лотов и подтверждение срока. Подробная проверка мощности относится к проверке поставщика, но карточка должна быть прочитана так, чтобы не подменять доступность товара общим утверждением о фабрике.
    """))

    add_main_subsection(doc, "15", "Incoterms®: правило, поименованное место и редакция", P("""
    Обозначение EXW, FOB или CIF в карточке не является достаточным условием поставки. Корректная запись включает правило, точное поименованное место или порт и редакцию, например FCA Shenzhen, China, Incoterms® 2020. Без места невозможно определить, до какой точки продавец несет расходы, где передает риск и какие операции включены в цену.

    EXW часто воспринимается как «самовывоз с фабрики», однако покупателю необходимо оценить погрузку, внутреннюю перевозку и экспортные формальности. FCA может точнее распределить обязанности при контейнерной перевозке. FOB, CFR и CIF предназначены для морской и внутренней водной перевозки; их механическое применение к авиационному или железнодорожному маршруту создает противоречия. CIF включает обязанность продавца организовать минимально предусмотренное правилами страхование, но не гарантирует достаточное покрытие конкретного риска.

    Incoterms® не определяют цену товара, переход права собственности, порядок оплаты, приемку, качество, санкции и разрешение споров. Поэтому карточка с отметкой «FOB price» дает только часть модели. Аналитик уточняет включенные локальные расходы, порт, тип груза и документы, а затем рассчитывает стоимость на сопоставимой точке.
    """))

    add_main_subsection(doc, "16", "Упаковка, маркировка и логистические параметры", P("""
    Упаковка влияет на сохранность, объемный вес, стоимость перевозки, требования склада и возможность реализации. Карточка может показывать красивую потребительскую коробку, но цена относится к нейтральному пакету. Необходимо различать первичную, групповую и транспортную упаковку, материалы, защиту от влаги, ударов и коррозии, паллетирование и ограничения штабелирования.

    Для расчета фиксируются размеры и масса каждой упаковочной ступени. Перевозчик может применять объемный вес, поэтому небольшое снижение габарита коробки заметно меняет стоимость авиационной или экспресс-доставки. Для деревянной упаковки проверяются требования к обработке и маркировке; для опасных грузов — специальные документы и упаковочные инструкции. Эти вопросы не выводятся из фотографии.

    Маркировка должна рассматриваться как отдельная спецификация: товарная, транспортная, обязательная в ЕАЭС, идентификационная и клиентская. Карточка с русскоязычной этикеткой другого заказчика не подтверждает готовность законно использовать ее. Покупатель определяет содержание, язык, место нанесения, стойкость и ответственность за макет.
    """))

    add_main_subsection(doc, "17", "Документы качества и подтверждение соответствия", P("""
    Упоминание CE, RoHS, ISO, FCC или иных обозначений в карточке требует осторожного толкования. Сертификат системы менеджмента относится к организации и области ее деятельности, а не автоматически к качеству каждой единицы. Отчет об испытаниях может относиться к другой модели, материалу или заказчику. Европейская маркировка не заменяет процедуры оценки соответствия, применимые в ЕАЭС.

    Для каждого документа фиксируются название, номер, владелец, орган или лаборатория, дата, срок, модель, стандарт и область действия. Картинка низкого разрешения рассматривается как сигнал наличия документа, но не как подтверждение. До импорта необходимо определить применимые технические регламенты ЕАЭС, форму оценки, заявителя, комплект доказательств и требования к маркировке.

    Карточка помогает выявить потенциально регулируемый товар и сформировать запрос, однако не должна использоваться для обещания клиенту, что «сертификация уже есть». Стоимость испытаний, образцов, перевода и маркировки включается в экономическую модель. Если продавец не может сопоставить документ с выбранной моделью, риск считается открытым.
    """))

    add_main_subsection(doc, "18", "Интеллектуальная собственность и признаки чужого контента", P("""
    Карточка может содержать известный товарный знак, дизайн, персонажа, патентованную конструкцию или фотографии правообладателя. Наличие предложения на площадке не означает законность производства и экспорта. Импортеру необходимо оценить риск нарушения прав в стране производства, транзита и ввоза, а также риск блокировки карточки, платежа или груза.

    Красными флагами являются намеренно скрытый логотип, предложение нанести любой бренд без документов, смешение оригинальных и «совместимых» обозначений, необычно низкая цена и отказ указать происхождение дизайна. Для запчастей и совместимых товаров важно корректное описание назначения и отсутствие впечатления официальной связи, если ее нет.

    Анализ карточки фиксирует объекты, требующие проверки: знак, внешний вид, упаковка, программное обеспечение, фото и инструкции. Если покупатель предоставляет собственный дизайн, он должен подтвердить права и ограничить использование файлов. Детальные договорные механизмы рассматриваются позднее, но закупочная позиция не должна переходить дальше при очевидном неразрешенном брендинге.
    """))

    add_main_subsection(doc, "19", "Платежные сведения и цена как часть платежного сценария", P("""
    Карточка может показывать доступные способы оплаты и значки защиты сделки, но конкретная доступность зависит от страны, суммы, категории, аккаунта и структуры заказа. Цена, согласованная в переписке, может не совпасть с суммой защищенного заказа, если продавец предлагает скидку за платеж вне площадки. Такое предложение изменяет не только комиссию, но и доказательственную и риск-позицию покупателя.

    На этапе анализа фиксируются предполагаемые этапы оплаты, комиссия платформы, валюта, получатель, условия возврата и момент, после которого защита не действует. Нельзя рассчитывать на общий значок без проверки правил конкретного заказа. Платеж третьему лицу, физическому лицу или на новый счет требует отдельной проверки и не оправдывается более низкой ценой.

    Полная коммерческая оценка включает стоимость финансирования аванса и размер незащищенной суммы. Два предложения с одинаковой ценой могут существенно различаться, если одно требует 100 процентов до производства, а другое допускает этапность и инспекцию перед остатком. Карточка дает только исходный сигнал; платежное обязательство должно быть сформировано в заказе и контракте.
    """))

    add_main_subsection(doc, "20", "Значки поставщика, верификация и статистика", P("""
    Площадки используют значки членства, аудита, верификации, периода работы, объема транзакций и скорости ответа. Они помогают фильтровать предложения, но не заменяют проверку конкретной компании и товара. Значок может подтверждать идентификацию юридического лица или посещение площадки третьей стороной, но не гарантировать исполнение будущего заказа, качество конкретной партии или отсутствие изменений после проверки.

    Аналитик раскрывает содержание показателя: кем проверено, когда, какие пункты охвачены, доступен ли отчет, совпадает ли юридическое лицо, адрес и профиль деятельности. Статистика сделок может охватывать другие товары, регионы и суммы. Высокая скорость ответа говорит об организации продаж, а не о производственной способности.

    Значки используются как веса в предварительной оценке, но каждый вывод формулируется ограниченно. Корректно: «площадка отображает статус Audited Supplier и отчет от указанной организации на такую-то дату». Некорректно: «поставщик гарантированно надежен». Такой язык дисциплинирует решение и предотвращает перенос доверия к платформе на неизвестные условия сделки.
    """))

    add_main_subsection(doc, "21", "Отзывы, заказы и социальное доказательство", P("""
    Отзывы могут дать сведения о коммуникации, упаковке, соответствии образцу и сроке, но их репрезентативность ограничена. Необходимо учитывать количество, давность, конкретный товар, объем заказа, страну покупателя и характер претензии. Средняя оценка без текста и доказательств менее информативна, чем подробный отзыв с фотографиями, однако и он не подтверждает характеристики будущей партии.

    Анализируется распределение, а не только среднее: повторяются ли жалобы на размер, цвет, задержку, замену материала или послепродажную поддержку. Резкий поток однотипных отзывов, несоответствие языка и товара, отсутствие проверяемого заказа снижают вес. Отсутствие отзывов для промышленного оборудования не обязательно негативно, поскольку сделки редки и конфиденциальны.

    Отзывы формируют вопросы и сценарии контроля. Если несколько покупателей отмечают слабую упаковку, это основание усилить спецификацию и инспекцию, но не автоматический запрет. Решение опирается на совокупность карточки, документов, образца, проверки контрагента и договорных механизмов.
    """))

    add_main_subsection(doc, "22", "Предварительная полная импортная себестоимость", P("""
    Цена карточки — лишь один элемент landed cost. Предварительная полная стоимость включает товар, кастомизацию, упаковку, внутреннюю логистику в КНР, экспортные операции, международную перевозку, страхование, терминальные расходы, услуги представителя, таможенную пошлину, налог на добавленную стоимость, оценку соответствия, маркировку, банковские комиссии, инспекцию, склад и резерв на брак.

    Расчет выполняется на выбранную партию и единицу. Таможенная стоимость определяется по правилам ЕАЭС и не равна автоматически цене FOB или сумме платежа; в нее включаются предусмотренные законодательством элементы. Пошлина зависит от классификации и базы, НДС рассчитывается по применимым правилам. До подтверждения кода и условий цифры являются сценарными, что должно быть явно обозначено.

    Полезно строить три сценария: базовый, неблагоприятный и стрессовый. В неблагоприятном увеличиваются фрахт, курс, процент брака и расходы на доработку; стрессовый отражает задержку, повторное испытание или частичную потерю партии. Такой анализ показывает, выдерживает ли экономика проекта неопределенности карточки.
    """), table=(("Элемент", "Источник данных", "Статус"), (
        ("Цена товара", "Карточка и котировка", "Подтвердить вариант, количество и валюту"),
        ("Упаковка и кастомизация", "Описание и отдельный расчет", "Часто не включены"),
        ("Логистика до границы", "Базис и ставка перевозчика", "Указать маршрут и период"),
        ("Таможенные платежи", "Классификационная гипотеза", "Сценарный расчет"),
        ("Соответствие и маркировка", "Регламенты и подрядчики", "Проверить до заказа"),
        ("Резерв риска", "Матрица неопределенностей", "Обосновать процент или сумму"),
    ), "Таблица 1. Структура предварительного landed cost"))

    add_main_subsection(doc, "23", "Матрица нормализации нескольких карточек", P("""
    Для сравнения создается единый набор полей. Каждая строка отражает критерий, каждый столбец — предложение. Значения копируются не механически, а приводятся к общей единице, партии и точке поставки. Неизвестное обозначается как «не подтверждено», а не заполняется оценкой без пометки. Рядом указывается источник: карточка, приложение, сообщение, расчет.

    Матрица должна отделять коммерческую привлекательность от качества данных. Поставщик с чуть более высокой ценой, но полной спецификацией и реалистичным сроком может иметь меньшую совокупную стоимость риска. Поля с высокой критичностью блокируют итоговый рейтинг до подтверждения: безопасность, совместимость, сторона платежа, обязательное соответствие, право на бренд.

    После нормализации формируется список расхождений и вопросов. Его задача — не выбрать победителя по количеству зеленых ячеек, а показать, какие условия сравнимы и что необходимо получить. Весовые оценки допустимы только после определения стоп-факторов: критическое несоответствие нельзя компенсировать низкой ценой.
    """), table=(("Критерий", "Карточка A", "Карточка B", "Правило нормализации"), (
        ("Модель и состав", "Базовая", "Комплект", "Сравнить одинаковую комплектацию"),
        ("MOQ", "500 шт.", "1 000 шт.", "Рассчитать сценарии для обоих объемов"),
        ("Цена", "EXW", "FOB Ningbo", "Привести к одной точке"),
        ("Упаковка", "Не указана", "Индивидуальная коробка", "Запросить стоимость и габариты"),
        ("Срок", "7–15 дней", "25 дней", "Определить начальную и конечную точку"),
        ("Документы", "Логотип CE", "Отчет на модель", "Проверить применимость и подлинность"),
    ), "Таблица 2. Пример матрицы нормализации"))

    add_main_subsection(doc, "24", "Красные флаги карточки товара", P("""
    Красный флаг — не доказательство мошенничества, а сигнал, требующий усиленной проверки или остановки. К типовым относятся цена существенно ниже рыночного диапазона без объяснения, несоответствие модели на фото и в параметрах, минимальная цена только для аксессуара, невозможный срок, отсутствие единицы, копии чужих изображений, обещание любых сертификатов, известный бренд без полномочий и предложение оплаты вне защищенного канала.

    Важны сочетания. Одна устаревшая фотография может быть редакционной ошибкой; одновременно новый аккаунт, чужой бренд, 100-процентный аванс на личный счет и отказ назвать модель создают критический профиль. Аналитик фиксирует наблюдаемые факты, последствия и требуемое действие. Формулировка «поставщик подозрительный» заменяется конкретной: «цена относится к варианту без двигателя, тогда как заголовок и первое фото показывают комплект; требуется новая котировка».

    Решение по карточке имеет три исхода: допустить к запросу уточнений, временно приостановить до доказательств или исключить. Сам факт красивого профиля не дает допуска, а отсутствие идеально оформленной карточки не исключает промышленного поставщика. Критерий — возможность получить непротиворечивую и проверяемую закупочную позицию.
    """), bullets=[
        "цена не связана с конкретным вариантом и количеством;",
        "разные единицы в заголовке, свойствах и упаковке;",
        "фото и параметры относятся к разным моделям;",
        "сертификаты показаны без номера, модели и области действия;",
        "базис указан без места либо не соответствует способу перевозки;",
        "срок не включает подготовку образца или кастомизацию;",
        "предлагается известный бренд без объяснения полномочий;",
        "продавец стимулирует оплату вне площадки ради сохранения цены."
    ])

    add_main_subsection(doc, "25", "Мини-кейс: три карточки одного товара", P("""
    Российская компания ищет 2 000 аккумуляторных светильников. Карточка A показывает 4,10 долл. EXW при MOQ 2 000, но цена относится к версии без аккумулятора и коробки. Карточка B показывает 5,30 долл. FOB Ningbo при MOQ 1 000, включает аккумулятор, нейтральную коробку и испытательный отчет на указанную модель. Карточка C на 1688 показывает эквивалент 3,90 долл., но цена внутренняя, минимальная партия 100, экспортная сторона и документы не определены.

    Прямое ранжирование дает преимущество C, затем A. После нормализации A получает аккумулятор 0,85 долл., коробку 0,18, внутреннюю доставку и экспортные расходы; B требует только логотип и международную перевозку; C требует посредника, экспортную наценку, проверку налога и отдельное подтверждение модели. Итоговая разница сокращается, а качество данных B оказывается выше.

    Правильный вывод не состоит в автоматическом выборе B. Аналитик формирует одинаковый RFQ, запрашивает размеры упаковки, срок, документы, цену образца и условия оплаты. К дальнейшему сравнению допускаются только ответы, в которых одна и та же модель связана с ценой и условиями. Кейс показывает, что задача чтения карточки — построить сравнимую основу, а не угадать окончательную цену.
    """))

    add_heading(doc, "8. Практико-ориентированный блок.", 1)

    add_practical_subsection(doc, "1", "Алгоритм анализа карточки", P("""
    Анализ рекомендуется выполнять в фиксированной последовательности. Она предотвращает ситуацию, когда привлекательная цена влияет на восприятие технических рисков. Сначала идентифицируется товар, затем проверяются параметры и единицы, после этого — цена и MOQ, далее сроки, упаковка, базис, документы и полная стоимость. Каждый шаг завершается записью факта, источника и статуса подтверждения.

    Итогом является не набор скриншотов, а протокол, понятный другому специалисту. Он должен отвечать на вопросы: какую модель анализировали, что включено, что известно только со слов карточки, какие расчеты выполнены, какие риски блокируют решение и что нужно спросить. При изменении карточки сохраняется новая версия, а старая не удаляется из досье.
    """), bullets=[
        "сохранить ссылку, дату, название продавца и скриншоты первого экрана;",
        "выбрать конкретный SKU и присвоить внутренний идентификатор;",
        "зафиксировать материал, размеры, функцию, комплектность и критические параметры;",
        "установить единицу цены, упаковочную единицу, MOQ и ценовые ступени;",
        "выделить образец, кастомизацию, оснастку и иные доплаты;",
        "уточнить срок, стартовую точку и готовность к отгрузке;",
        "записать правило Incoterms®, место, редакцию и включенные локальные расходы;",
        "проверить упаковку, вес, объем, маркировку и логистические ограничения;",
        "составить перечень документов и применимых процедур соответствия;",
        "рассчитать landed cost по сценариям и оформить вопросы."
    ])

    add_practical_subsection(doc, "2", "Чек-лист логической согласованности", P("""
    Перед передачей карточки в закупочную работу полезно провести арифметическую и смысловую проверку. Она не требует ответа продавца и выявляет значительную часть ошибок интерфейса, перевода и копирования. Все вычисления сохраняются с формулой, а исходные значения не перезаписываются.
    """), bullets=[
        "совпадает ли модель на фото, в заголовке и таблице параметров;",
        "соответствует ли минимальная цена выбранному варианту;",
        "можно ли однозначно определить, за что указана цена;",
        "согласованы ли MOQ, количество в коробке и кратность заказа;",
        "реалистичны ли масса и объем упаковки;",
        "включены ли аккумулятор, адаптер, кабель, крепеж и инструкция;",
        "совместимы ли напряжение, частота, вилка и маркировка с рынком ввоза;",
        "применим ли указанный базис к способу перевозки;",
        "относятся ли документы к той же модели и юридическому лицу;",
        "не скрывает ли цена обязательную кастомизацию, форму или экспортную наценку."
    ])

    add_practical_subsection(doc, "3", "Форма протокола анализа", P("""
    Протокол может быть реализован в таблице или системе закупок. Для каждого поля полезны четыре колонки: значение, источник, статус и комментарий о влиянии. Статусы должны быть единообразными: подтверждено документом, заявлено в карточке, рассчитано, противоречиво, отсутствует. Цвет используется только как визуальное дополнение; смысл должен читаться без цвета.

    К протоколу прикладываются скриншоты, PDF, экспорт страницы и расчеты. Названия файлов включают дату и внутренний номер позиции. Это особенно важно, когда продавец меняет карточку после переговоров или несколько сотрудников работают с похожими ссылками.
    """), table=(("Поле", "Значение", "Источник/дата", "Статус и действие"), (
        ("Модель", "LT-2000-A", "Карточка, 15.07.2026", "Заявлено; запросить datasheet"),
        ("Комплект", "Светильник + кабель", "Фото и описание", "Противоречие по адаптеру"),
        ("Цена", "5,30 USD/шт.", "Ступень 1 000–2 999", "Уточнить для 2 000 шт."),
        ("Базис", "FOB", "Первый экран", "Нет порта и редакции"),
        ("Упаковка", "50 шт./короб", "Инфографика", "Проверить массу брутто"),
        ("Документы", "Test report", "Изображение", "Запросить полный файл и модель"),
    ), "Таблица 3. Фрагмент протокола"))

    add_practical_subsection(doc, "4", "Расчетный кейс landed cost", P("""
    Карточка показывает цену 6,00 долл. за единицу при партии 3 000 штук EXW. Индивидуальная упаковка стоит 0,20 долл., логотип — 0,08, внутренняя доставка и экспортные операции — 1 200 долл., международная перевозка и страхование — 4 500 долл. Для учебного расчета таможенная пошлина принимается 5 процентов от расчетной таможенной стоимости, НДС — 20 процентов по условной базе, инспекция и документы — 1 800 долл. Фактические ставки и база должны определяться по применимому законодательству и классификации.

    Стоимость товара с упаковкой и логотипом: 18 840 долл. Добавление расходов до границы дает 24 540 долл. Условная пошлина — 1 227 долл.; условный НДС — 5 153,40 долл.; инспекция и документы — 1 800 долл. Общая сумма — 32 720,40 долл., или 10,91 долл. за единицу без учета внутренней логистики после выпуска, банковских расходов и резерва. Цена карточки составляла лишь 55 процентов полученной величины.

    Учебный смысл кейса — не запомнить процент, а увидеть структуру. Если упаковка увеличит объем на 20 процентов, перевозка может измениться. Если код ТН ВЭД или налоговая база иные, меняются платежи. Поэтому каждая цифра снабжается источником и диапазоном, а решение принимается по сценариям.
    """))

    add_practical_subsection(doc, "5", "Типовые ошибки и корректирующие действия", P("""
    Ошибки анализа обычно возникают не из-за отсутствия информации, а из-за неявных предположений. Сотрудник видит знакомое фото и считает комплектацию очевидной; использует нижнюю цену диапазона; переводит юани по текущему курсу, но не учитывает экспортную структуру; считает FOB ценой «с доставкой»; принимает картинку сертификата за готовность к выпуску.

    Корректирующее действие состоит в формализации. Каждое предположение заменяется полем и статусом, расчеты выполняются на общей базе, а критические значения подтверждаются документом. Руководитель получает не эмоциональное заключение, а перечень открытых условий и стоимость их влияния.
    """), table=(("Ошибка", "Риск", "Корректирующее действие"), (
        ("Взята минимальная цена диапазона", "Занижение бюджета", "Связать цену с SKU и объемом"),
        ("Не учтена упаковочная единица", "Ошибка количества и логистики", "Проверить коэффициенты пересчета"),
        ("Сертификат оценен по логотипу", "Отказ в выпуске или продаже", "Проверить документ и применимость"),
        ("FOB без порта", "Неясные локальные расходы", "Указать порт и Incoterms® 2020"),
        ("Отзывы заменили техническую проверку", "Несоответствие партии", "Сформировать измеримую спецификацию"),
        ("Карточка не сохранена", "Утрата исходных доказательств", "Архивировать дату, ссылку и скриншоты"),
    ), "Таблица 4. Ошибки анализа"))

